<script setup>
import {computed,ref,watch,onBeforeUnmount} from 'vue';
import {t,sanitize,api,notify} from '../store';
import Icon from './Icon.vue';
const props=defineProps({question:{required:true},modelValue:{default:null},attemptId:String,disabled:Boolean,preview:Boolean,timeRemaining:{default:null}});const emit=defineEmits(['update:modelValue','busy']);
const q=computed(()=>props.question),meta=computed(()=>q.value.metadata||{}),options=computed(()=>Array.isArray(q.value.options)?q.value.options:[]),value=computed({get:()=>props.modelValue,set:v=>emit('update:modelValue',v)});
const textTypes=['short_answer','essay','fill_blank'];
const leftItems=computed(()=>meta.value.left_items||options.value);
const blankItems=computed(()=>Array.isArray(meta.value.blanks)?meta.value.blanks:[]);
const dragTarget=ref('');
function shuffled(ids){const copy=[...ids];for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy}
const initialOrder=shuffled(options.value.map(choiceId));
function choiceId(option,i){return typeof option==='object'?(option.id??String(i)):String(i)}function choiceText(option){return typeof option==='object'?(option.text??option.label??''):option}
function toggle(id){const arr=Array.isArray(value.value)?[...value.value]:[];const i=arr.indexOf(id);if(i<0)arr.push(id);else arr.splice(i,1);value.value=arr}
const order=computed(()=>Array.isArray(value.value)&&value.value.length?value.value:initialOrder);
function move(index,delta){const arr=[...order.value],next=index+delta;if(next<0||next>=arr.length)return;[arr[index],arr[next]]=[arr[next],arr[index]];value.value=arr}
let dragged=null;function drop(index){if(dragged===null)return;const arr=[...order.value],entry=arr.splice(dragged,1)[0];arr.splice(index,0,entry);value.value=arr;dragged=null}
const matching=computed(()=>meta.value.right_items||meta.value.matches||meta.value.right_options||options.value.map((o,i)=>({id:o.match_id||o.id||String(i),text:o.match||o.target||o.text})));
function setMatch(key,response){value.value={...(typeof value.value==='object'?value.value:{}),[key]:response}}
const mediaId=computed(()=>meta.value.media_asset_id||q.value.media_asset_id||q.value.group?.media_asset_id||q.value.group?.media_asset?.id),mediaUrl=computed(()=>mediaId.value?'/api/media/'+mediaId.value:meta.value.audio_url||meta.value.video_url||meta.value.image_url||q.value.group?.media_asset?.url||null);
function storedCount(key){try{return Number(sessionStorage.getItem(key)||0)}catch(e){return 0}}
function saveCount(key,value){try{sessionStorage.setItem(key,String(value))}catch(e){}}
const plays=ref(props.preview?0:storedCount('inbaf-plays-'+q.value.key)),playLimit=computed(()=>Number(meta.value.max_plays??meta.value.play_limit??q.value.group?.metadata?.max_plays??((meta.value.allow_replay??q.value.group?.metadata?.allow_replay)===false?1:0)));const audio=ref(null),audioPlaying=ref(false),audioEnded=ref(false),audioTime=ref(0),audioDuration=ref(0),mediaError=ref(false);let audioRunStarted=false;
async function toggleAudio(){if(!audio.value||props.disabled)return;try{if(audio.value.paused){if(audioEnded.value){if(playLimit.value&&plays.value>=playLimit.value)return;audio.value.currentTime=0;audioEnded.value=false}await audio.value.play()}else audio.value.pause()}catch(e){mediaError.value=true}}
function audioFinished(){audioPlaying.value=false;audioEnded.value=true;audioTime.value=audioDuration.value;audioRunStarted=false}
function audioClock(seconds){if(!Number.isFinite(seconds))return '0:00';return Math.floor(seconds/60)+':'+String(Math.floor(seconds%60)).padStart(2,'0')}
function played(){if(!audioRunStarted){if(playLimit.value&&plays.value>=playLimit.value){audio.value.pause();audioPlaying.value=false;notify('Playback limit reached.',true);return}audioRunStarted=true;plays.value++;if(!props.preview)saveCount('inbaf-plays-'+q.value.key,plays.value)}audioPlaying.value=true}
const recording=ref(false),recordUrl=ref(''),uploading=ref(false),recordError=ref(''),recordSeconds=ref(0),prepSeconds=ref(0),recordCount=ref(props.preview?0:storedCount('inbaf-recordings-'+q.value.key));let recorder,stream,chunks=[],recordInterval,prepInterval,blob;
watch([recording,uploading,prepSeconds],()=>emit('busy',recording.value||uploading.value||prepSeconds.value>0));
const recordingLimit=computed(()=>Number(meta.value.recording_seconds||meta.value.response_seconds||meta.value.max_duration_seconds||120));
const attemptsLeft=computed(()=>Number(meta.value.max_recordings||meta.value.max_retries||3)-recordCount.value);
async function beginRecording(){recordError.value='';try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Microphone recording needs HTTPS or localhost and a supported browser.');stream=await navigator.mediaDevices.getUserMedia({audio:true});const prep=Number(meta.value.preparation_seconds||meta.value.prep_seconds||0);if(prep&&recordCount.value===0){prepSeconds.value=prep;prepInterval=setInterval(()=>{if(--prepSeconds.value<=0){clearInterval(prepInterval);startRecorder()}},1000)}else startRecorder()}catch(e){recordError.value=e.message;stream?.getTracks().forEach(track=>track.stop())}}
function startRecorder(){chunks=[];recordSeconds.value=0;const mime=['audio/webm;codecs=opus','audio/webm','audio/mp4'].find(m=>MediaRecorder.isTypeSupported(m));recorder=new MediaRecorder(stream,mime?{mimeType:mime}:{});recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=async()=>{blob=new Blob(chunks,{type:recorder.mimeType});if(recordUrl.value)URL.revokeObjectURL(recordUrl.value);recordUrl.value=URL.createObjectURL(blob);stream?.getTracks().forEach(t=>t.stop());recordCount.value++;if(!props.preview)saveCount('inbaf-recordings-'+q.value.key,recordCount.value);if(!props.preview)await uploadRecording()};recorder.start();recording.value=true;recordInterval=setInterval(()=>{recordSeconds.value++;if(recordSeconds.value>=recordingLimit.value||(props.timeRemaining!==null&&props.timeRemaining<=2))stopRecording()},1000)}
function stopRecording(){if(recorder?.state==='recording')recorder.stop();recording.value=false;clearInterval(recordInterval)}
async function uploadRecording(){if(!blob||!props.attemptId)return;uploading.value=true;recordError.value='';try{const form=new FormData();form.append('file',blob,'speaking-'+q.value.key+(blob.type.includes('mp4')?'.m4a':'.webm'));form.append('question_key',q.value.key);form.append('duration',String(recordSeconds.value));const result=await api('/attempts/'+props.attemptId+'/recordings',{method:'POST',body:form});value.value=result.answer?.response||result.recording||result.response;notify(t('recordSaved'))}catch(e){recordError.value=e.message}finally{uploading.value=false}}
watch(()=>props.disabled,disabled=>{if(disabled){if(recording.value)stopRecording();if(prepSeconds.value){clearInterval(prepInterval);prepSeconds.value=0;stream?.getTracks().forEach(track=>track.stop())}}});
onBeforeUnmount(()=>{clearInterval(recordInterval);clearInterval(prepInterval);if(recorder?.state==='recording')recorder.stop();stream?.getTracks().forEach(t=>t.stop());if(recordUrl.value)URL.revokeObjectURL(recordUrl.value)});
</script>
<template>
<div class="question-content"><div class="question-columns" :class="{'has-passage':q.group?.content}"><div v-if="q.group?.content" class="reading-passage" tabindex="0" role="region" :aria-label="q.group.title||'Reading passage / Teks bacaan'"><span class="eyebrow">{{q.group.title||'READING PASSAGE'}}</span><div class="rich-content" v-html="sanitize(q.group.content)"></div></div><div class="question-response"><div v-if="q.instructions" class="question-instruction" v-html="sanitize(q.instructions)"></div><h2 v-if="q.title" class="question-title">{{q.title}}</h2><div class="question-prompt rich-content" v-html="sanitize(q.prompt)"></div>
<div v-if="mediaUrl" class="question-media"><template v-if="q.type==='listening'||q.group?.kind==='audio'||meta.media_kind==='audio'"><audio ref="audio" :src="mediaUrl" :controls="!playLimit" controlslist="nodownload" @play="played" @pause="audioPlaying=false" @ended="audioFinished" @timeupdate="audioTime=$event.target.currentTime" @loadedmetadata="audioDuration=$event.target.duration" @error="mediaError=true"></audio><div v-if="playLimit" class="restricted-audio-player"><button class="audio-play-button" @click="toggleAudio" :disabled="disabled||(audioEnded&&plays>=playLimit)" :aria-label="audioPlaying?'Pause audio':'Play audio'"><Icon :name="audioPlaying?'Pause':'Play'" :size="19"/></button><div class="audio-progress-content"><span>Listening material<small>{{audioClock(audioTime)}} / {{audioClock(audioDuration)}}</small></span><progress :value="audioTime" :max="audioDuration||1" aria-label="Audio playback progress"></progress></div><Icon name="Volume2" :size="19"/></div></template><video v-else-if="q.type==='video'||q.group?.kind==='video'" :src="mediaUrl" controls controlslist="nodownload"></video><img v-else-if="q.type==='image'||q.group?.kind==='image'" :src="mediaUrl" alt="Assessment illustration"><div v-if="mediaError" class="inline-error">The media could not be loaded. Check your connection.<button class="text-button" @click="mediaError=false;audio?.load()">Retry audio</button></div><small v-if="playLimit">Playback {{Math.min(plays,playLimit)}} / {{playLimit}}</small></div>
<div v-if="textTypes.includes(q.type)&&!blankItems.length" class="response-text"><textarea v-if="q.type==='essay'" v-model="value" :disabled="disabled" :placeholder="t('write')" rows="10" :maxlength="meta.max_length||50000"></textarea><input v-else v-model="value" :disabled="disabled" :placeholder="t('write')" :maxlength="meta.max_length||2000"><div v-if="q.type==='essay'" class="editor-footer"><span><Icon name="AlignLeft" :size="15"/>{{String(value||'').trim().split(/\s+/).filter(Boolean).length}} {{t('wordCount')}}</span><span v-if="meta.min_words">Suggested minimum: {{meta.min_words}} words</span><span><Icon name="CloudCheck" :size="15"/>Auto-save enabled</span></div></div>
<div v-else-if="q.type==='speaking'" class="speaking-response"><span class="speaking-icon" :class="{recording}"><Icon name="Mic" :size="33"/></span><h3>{{prepSeconds?'Prepare your response':recording?'Recording your response':recordUrl?'Your response is ready':'Let your voice be heard.'}}</h3><p>{{t('micPermission')}}</p><div v-if="prepSeconds" class="record-timer">{{prepSeconds}}s preparation</div><div v-else-if="recording" class="record-timer"><span class="record-dot"></span>{{String(Math.floor(recordSeconds/60)).padStart(2,'0')}}:{{String(recordSeconds%60).padStart(2,'0')}} / {{Math.floor(recordingLimit/60)}}:{{String(recordingLimit%60).padStart(2,'0')}}</div><audio v-if="recordUrl" :src="recordUrl" controls></audio><audio v-else-if="value?.url||value?.media_asset_id||value?.recording_id" :src="value.url||('/api/media/'+(value.media_asset_id||value.recording_id))" controls></audio><div v-if="recordError" class="inline-error">{{recordError}}<button v-if="blob" class="text-button" @click="uploadRecording">Retry upload</button></div><button v-if="recording" class="button danger" @click="stopRecording"><Icon name="Square" :size="16"/>{{t('stopRecord')}}</button><button v-else class="button" @click="beginRecording" :disabled="disabled||uploading||prepSeconds>0||attemptsLeft<=0"><Icon name="Mic" :size="17"/>{{uploading?'Uploading recording…':recordUrl?t('retry'):t('record')}}</button><small>{{attemptsLeft}} recording attempts remaining · Maximum {{recordingLimit}} seconds</small></div>
<div v-else-if="['sentence_ordering','word_ordering'].includes(q.type)" class="ordering-response"><p class="muted">Drag items into the correct order, or use the arrow buttons.</p><div v-for="(key,i) in order" :key="key" class="ordering-item" draggable="true" @dragstart="dragged=i" @dragover.prevent @drop.prevent="drop(i)"><Icon name="GripVertical" :size="18"/><span class="order-number">{{i+1}}</span><span>{{choiceText(options.find((o,j)=>choiceId(o,j)===key)||key)}}</span><button class="icon-button" :disabled="disabled||i===0" @click="move(i,-1)" aria-label="Move up"><Icon name="ChevronUp" :size="17"/></button><button class="icon-button" :disabled="disabled||i===order.length-1" @click="move(i,1)" aria-label="Move down"><Icon name="ChevronDown" :size="17"/></button></div><button class="button secondary confirm-order-button" :disabled="disabled" @click="value=[...order]"><Icon name="Check" :size="16"/>Confirm this order</button></div>
<div v-else-if="['matching','drag_drop'].includes(q.type)" class="matching-response"><div v-if="q.type==='drag_drop'" class="drag-tokens"><span v-for="(right,j) in matching" :key="j" draggable="true" @dragstart="dragTarget=String(right.id??j)" class="drag-token"><Icon name="GripVertical" :size="15"/>{{right.text??right}}</span></div><div v-for="(option,i) in leftItems" :key="choiceId(option,i)" class="matching-item" @dragover.prevent @drop.prevent="!disabled&&dragTarget&&setMatch(choiceId(option,i),dragTarget)"><span>{{choiceText(option)}}</span><Icon name="ArrowRight" :size="17"/><select :value="value?.[choiceId(option,i)]||''" @change="setMatch(choiceId(option,i),$event.target.value)" :disabled="disabled"><option value="">{{t('select')}}</option><option v-for="(right,j) in matching" :key="j" :value="right.id??j">{{right.text??right}}</option></select></div></div>
<div v-else-if="['dropdown','fill_blank'].includes(q.type)&&blankItems.length" class="blank-response"><label v-for="(blank,i) in blankItems" :key="blank.id||i">{{blank.label||('Blank '+(i+1))}}<select v-if="q.type==='dropdown'" :value="value?.[blank.id]||''" @change="setMatch(blank.id,$event.target.value)" :disabled="disabled"><option value="">{{t('select')}}</option><option v-for="(option,j) in blank.options||options" :key="j" :value="choiceId(option,j)">{{choiceText(option)}}</option></select><input v-else :value="value?.[blank.id]||''" @input="setMatch(blank.id,$event.target.value)" :disabled="disabled" :placeholder="t('write')"></label></div><div v-else-if="q.type==='dropdown'" class="dropdown-response"><select v-model="value" :disabled="disabled"><option :value="null">{{t('select')}}</option><option v-for="(option,i) in options" :key="i" :value="choiceId(option,i)">{{choiceText(option)}}</option></select></div>
<div v-else-if="q.type==='true_false'" class="choice-options"><label v-for="option in [{id:'true',text:'True / Benar'},{id:'false',text:'False / Salah'}]" :key="option.id" class="choice-option" :class="{chosen:String(value)===option.id}"><input type="radio" :name="'question-'+q.key" :value="option.id" v-model="value" :disabled="disabled"><span class="choice-letter">{{option.id==='true'?'T':'F'}}</span><span>{{option.text}}</span><Icon v-if="String(value)===option.id" name="CircleCheck" :size="20"/></label></div>
<div v-else class="choice-options"><label v-for="(option,i) in options" :key="choiceId(option,i)" class="choice-option" :class="{chosen:q.type==='multiple_response'?Array.isArray(value)&&value.includes(choiceId(option,i)):String(value)===String(choiceId(option,i))}"><input :type="q.type==='multiple_response'?'checkbox':'radio'" :name="'question-'+q.key" :value="choiceId(option,i)" :checked="q.type==='multiple_response'?Array.isArray(value)&&value.includes(choiceId(option,i)):String(value)===String(choiceId(option,i))" @change="q.type==='multiple_response'?toggle(choiceId(option,i)):value=choiceId(option,i)" :disabled="disabled"><span class="choice-letter">{{String.fromCharCode(65+i)}}</span><span v-html="sanitize(choiceText(option))"></span><Icon v-if="q.type==='multiple_response'?Array.isArray(value)&&value.includes(choiceId(option,i)):String(value)===String(choiceId(option,i))" name="CircleCheck" :size="20"/></label><p v-if="!options.length" class="muted">This question has no answer options. Please contact your assessment administrator.</p></div>
</div></div></div>
</template>
<style scoped>
.question-content,.question-columns,.question-response{min-width:0;max-width:100%}.question-content{container-type:inline-size}.question-columns{display:grid;grid-template-columns:minmax(0,1fr);gap:1.5rem}.question-content .reading-passage{margin:0;min-width:0;max-height:none;overflow-wrap:anywhere}.reading-passage>.eyebrow{display:block;margin-bottom:1rem}.question-response :deep(.rich-content),.reading-passage :deep(.rich-content){overflow-wrap:anywhere}.question-response :deep(.rich-content img),.reading-passage :deep(.rich-content img){height:auto;max-width:100%}.question-response :deep(.rich-content table),.reading-passage :deep(.rich-content table){display:block;overflow-x:auto;max-width:100%;white-space:normal}.question-response .question-title{font-size:1.375rem;line-height:1.65}.question-response .question-prompt{font-size:1.3125rem;line-height:1.8}.question-response .question-instruction{font-size:1.125rem;line-height:1.7;overflow-wrap:anywhere}.question-response .choice-option{border-color:var(--border);align-items:flex-start;color:var(--text);overflow-wrap:anywhere}.question-response .choice-option.chosen{background:var(--blue-soft);border-color:var(--color-accent);color:var(--text)}.question-response .choice-option .choice-letter{border-color:var(--border);color:var(--text)}.question-response .choice-option.chosen .choice-letter{background:var(--color-primary);color:var(--color-background-dark,#092522);border-color:var(--color-primary)}.choice-option>svg{flex-shrink:0;margin-top:.5rem;color:var(--color-accent)}.question-response .choice-option>input:disabled{cursor:not-allowed}.question-response .choice-option:has(input:focus-visible){outline:3px solid var(--color-accent);outline-offset:3px}.question-response .choice-option:has(input:disabled){cursor:not-allowed}.question-response .question-media{padding:1rem}.question-media audio,.question-media video,.speaking-response audio{max-width:100%;min-width:0}.question-response .audio-progress-content>span{flex-wrap:wrap;gap:.5rem}.question-response .restricted-audio-player{gap:.75rem}.restricted-audio-player>svg{flex-shrink:0}.question-response .speaking-response{padding:1.5rem 1rem;border-color:var(--border);overflow-wrap:anywhere}.question-response .speaking-icon{color:var(--color-accent);background:var(--blue-soft);border-color:var(--border)}.question-response .speaking-response h3{font-size:1.375rem;line-height:1.6}.question-response .speaking-response>small{color:var(--muted);font-size:1.0625rem;line-height:1.7}.record-timer{max-width:100%;flex-wrap:wrap;justify-content:center}.question-response .ordering-item{display:grid;grid-template-columns:auto auto minmax(0,1fr) auto auto;gap:.75rem;color:var(--text);overflow-wrap:anywhere}.question-response .ordering-item>.icon-button{min-width:44px;min-height:44px;width:44px;height:44px;margin:0}.question-response .order-number{background:var(--blue-soft);color:var(--color-accent)}.question-response .matching-item{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);gap:1rem;color:var(--text);overflow-wrap:anywhere}.question-response .matching-item>select{width:100%;min-width:0;max-width:100%;font-size:1.125rem}.question-response .drag-token{color:var(--color-accent);border-color:var(--border);max-width:100%;overflow-wrap:anywhere;white-space:normal}.question-response .blank-response,.question-response .dropdown-response{max-width:100%;min-width:0}.blank-response label{font-size:1.125rem;line-height:1.6}.question-response .dropdown-response>select,.question-response .blank-response select,.question-response .blank-response input{width:100%;min-width:0;max-width:100%;font-size:1.125rem}.question-response .response-text{min-width:0}.question-response .response-text textarea{resize:vertical;max-width:100%;min-height:15rem}.question-response .editor-footer{font-size:1.0625rem;color:var(--muted);line-height:1.65}.question-response .editor-footer>span{align-items:flex-start}.question-response .editor-footer svg{flex-shrink:0;margin-top:.3rem}
@container(min-width:48rem){.question-columns.has-passage{grid-template-columns:minmax(0,1fr) minmax(0,1.05fr);align-items:start;gap:2rem}.question-columns.has-passage .reading-passage{position:sticky;top:calc(var(--exam-header-height,6rem) + 1rem);max-height:calc(100dvh - var(--exam-header-height,6rem) - 3rem);overflow:auto;overscroll-behavior:contain;scrollbar-gutter:stable}.has-passage .question-response .matching-item{grid-template-columns:minmax(0,1fr)}.has-passage .matching-item>svg{display:none}}
@media(max-width:600px){.question-columns{gap:1rem}.question-response .matching-item{grid-template-columns:minmax(0,1fr)}.matching-item>svg{display:none}.question-response .ordering-item{grid-template-columns:auto minmax(0,1fr) auto auto;gap:.5rem}.ordering-item>svg{display:none}.question-response .ordering-item>span:nth-of-type(2){grid-column:2/-1;grid-row:1}.question-response .ordering-item>.icon-button:first-of-type{grid-column:3}.question-response .choice-option{padding:1rem .75rem;gap:.75rem}.question-response .choice-option.chosen{padding:calc(1rem - 1px) calc(.75rem - 1px)}.question-response .question-media{padding:.75rem}}
</style>